                {
                    memcpy((char*)out + pixel_offset, pixel, pixel_size);

                    pixel_offset = pixel_offset + pixel_size;
                }
                else
                {
                    const unsigned int adam7_x_start[7] = { 0, 4, 0, 2, 0, 1, 0 };
                    const unsigned int adam7_y_start[7] = { 0, 0, 4, 0, 2, 0, 1 };
