int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size)
{
    unsigned long int buffer_length = 1;
    unsigned char *buffer = NULL;
    int z_status = 0;

    if (size > 0)
        buffer_length *= data[0];
    if (size > 1)
